from ..exception import WrongDataFormat
from ..utils.logger import logger


class ConfigValidator:

    def validate(self, data):
        """Validate provided data.

        :param dictionary data: QC configuration represented by dictionary.

        :return: Positive value if configuration has proper format.
        :rtype: boolean
        """
        try:
            self._check_branch(data)
            return True
        except WrongDataFormat as e:
            logger.error(e)
            return False

    def _check_branch(self, data):
        self._check_if_dict(data)
        for key, value in list(data.items()):
            if key not in ["label", "qc_project", "qc_domain"]:
                self._check_if_dict(value)
                self._check_qc_path(value)

    def _check_qc_path(self, data):
        self._check_if_dict(data)
        for key, value in list(data.items()):
            if key not in ["label", "qc_project", "qc_domain"]:
                self._check_if_qc_path(key)
                self._check_test_suite(value)

    def _check_test_suite(self, data):
        self._check_if_dict(data)
        for key, value in list(data.items()):
            self._check_test_instance_regexp(value)

    def _check_test_instance_regexp(self, data):
        self._check_if_list(data)
        for each in data:
            self._check_if_string(each)

    def _check_if_qc_path(self, key):
        if "\\" not in key:
            raise WrongDataFormat(
                f"Expecting path like string (with \\\\ characters) for: {key}"
            )

    def _check_if_dict(self, data):
        if not isinstance(data, dict):
            raise WrongDataFormat(f"Expecting dictionary, got: {type(data)}")

    def _check_if_string(self, data):
        if not isinstance(data, str):
            raise WrongDataFormat(f"Expecting string, got: {type(data)}")

    def _check_if_list(self, data):
        if not isinstance(data, list):
            raise WrongDataFormat(f"Expecting list, got: {type(data)}")
